import{_ as e,o as t,c as o,Q as r}from"./chunks/framework.b67c47e6.js";const s="/assets/report-form.6a80f063.svg",a="/assets/file-defaults.40ebf862.svg",i="/assets/reports-table.9277a472.svg",b=JSON.parse('{"title":"Reports","description":"","frontmatter":{},"headers":[],"relativePath":"guide/reports/index.md","filePath":"guide/reports/index.md","lastUpdated":1790346505000}'),n={name:"guide/reports/index.md"},l=r('<h1 id="reports" tabindex="-1">Reports <a class="header-anchor" href="#reports" aria-label="Permalink to &quot;Reports&quot;">​</a></h1><p>Reports let you generate documents from your project data — Bills of Materials, production spreadsheets, QR stickers, quality control PDFs, and more.</p><nav class="table-of-contents"><ul><li><a href="#creating-a-report">Creating a Report</a></li><li><a href="#file-defaults">File Defaults</a></li><li><a href="#generation-templates">Generation Templates</a></li><li><a href="#report-status">Report Status</a><ul><li><a href="#document-status">Document status</a></li></ul></li><li><a href="#versioning">Versioning</a></li><li><a href="#content-selection">Content Selection</a></li><li><a href="#project-reports-vs-company-reports">Project Reports vs. Company Reports</a></li><li><a href="#report-types">Report Types</a><ul><li><a href="#bills-of-materials">Bills of Materials</a></li><li><a href="#other-reports">Other Reports</a></li><li><a href="#machine-files">Machine Files</a></li></ul></li></ul></nav><h2 id="creating-a-report" tabindex="-1">Creating a Report <a class="header-anchor" href="#creating-a-report" aria-label="Permalink to &quot;Creating a Report&quot;">​</a></h2><ol><li>Go to <strong>Production files</strong> (machine files and shop-floor documents) or <strong>Management files</strong> (quality, worktime and issue reports). Both exist inside a project and company-wide, under the Files section of the menu.</li><li>Click <strong>New production file</strong> or <strong>New management file</strong>.</li><li>In the report form dialog: <ul><li>Select the <strong>Report Type</strong> (e.g., Plates BoM, Production Excel). The list only shows the types of the view you are in, and machine files only when one of your machines produces them.</li><li>Optionally add a <strong>Document comment</strong> and pick a <strong>Document status</strong> (<em>For information</em>, <em>For ordering</em> or <em>Temporary</em>). In PDF documents the status is printed in the page header and the comment on the cover page. The comment is also added to the file name.</li><li>Configure the <strong>Document settings</strong> specific to the report type.</li><li>Choose which <strong>assemblies or modules</strong> to include.</li></ul></li><li>Click <strong>Submit</strong> to queue the report for generation.</li></ol><p><img src="'+s+'" alt="The report form"></p><ol><li>The <strong>Report Type</strong>.</li><li>The <strong>Document status</strong>, printed in the header of PDF documents.</li><li>The <strong>Document settings</strong> of the type. <strong>Form Content</strong> shows them as JSON.</li><li>More choices for some types: here, the materials to include.</li><li>The assemblies or modules to include. Ready ones are marked, and so are multipanel groups.</li><li><strong>Submit</strong>. The arrow next to it holds <strong>Save without generating</strong> (see the tip below).</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>When you edit an existing report (pencil icon), the arrow next to <strong>Submit</strong> offers <strong>Save without generating</strong>. It stores the changed settings without creating a new version. <strong>Submit</strong> saves them and generates a new version. For a new report, both start generation.</p></div><h2 id="file-defaults" tabindex="-1">File Defaults <a class="header-anchor" href="#file-defaults" aria-label="Permalink to &quot;File Defaults&quot;">​</a></h2><p>Each document type has a set of options — cover page, how parts are grouped, table style, paper size, and so on. <strong>File settings</strong> lets you set what those options start at, per type, for the whole company.</p><p>Open <strong>File settings</strong> in the Files section of the company menu, expand <strong>File defaults</strong>, and pick a type. The types are listed under <em>Production documents</em> and <em>Management documents</em>. The form is the same one you see when creating the file. Save, and every new file of that type starts from your values.</p><ul><li>A type with nothing saved shows <strong>System defaults</strong> and uses the values built into Produuz.it.</li><li>A type you have configured shows <strong>Custom defaults</strong>. <strong>Reset</strong> puts it back to the system values.</li><li>Files already created keep the settings they were saved with. Changing a default never changes a document you generated earlier.</li><li>Files generated from a template use these defaults too.</li></ul><p><img src="'+a+'" alt="File settings: File defaults"></p><ol><li>A type with defaults of your own. <strong>Reset</strong> puts it back to the system values.</li><li>A type that uses the values built into produuz.it.</li></ol><p><strong>Machine files are not in this list.</strong> Their options depend on the machine model, so their defaults live on the machine setup, in <strong>Production settings → Machine Settings</strong>.</p><h2 id="generation-templates" tabindex="-1">Generation Templates <a class="header-anchor" href="#generation-templates" aria-label="Permalink to &quot;Generation Templates&quot;">​</a></h2><p>A generation template is a saved set of files you always create together — for example a Plates BoM, a Wood BoM and the QR stickers for the same panels. Instead of filling the report form three times, you pick the template, select the panels once, and every file in it is queued in one action.</p><p>Templates are managed in <strong>File settings</strong> → <strong>File generation templates</strong>, under the Files section of the company menu. Each file in a template is one document type, plus the machine or production line it should use when the type needs one.</p><p>To use one, open a project and click <strong>Run template</strong> in Production files or Management files, choose the template, select the panels and click <strong>Generate</strong>. You can also create a template on the spot with <strong>New template</strong> in that same dialog. Templates run inside a project only: in the company-wide views the dialog asks you to pick a project first.</p><h2 id="report-status" tabindex="-1">Report Status <a class="header-anchor" href="#report-status" aria-label="Permalink to &quot;Report Status&quot;">​</a></h2><p><img src="'+i+'" alt="Production files"></p><ol><li><strong>Run template</strong> and <strong>New production file</strong>. The field next to them filters the list by machine or production line.</li><li>The status of the last generation: a chip, or a bar while it is working.</li><li>A newer IFC arrived for some of the designs in this report. Hover it to see which.</li><li>The row actions: download, delete, edit, set as final, clone and generate again.</li><li>The versions of the report, under an expanded row.</li></ol><p>Once submitted, a report goes through these stages:</p><table><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>initializing</strong></td><td>Queued for processing; the job will start shortly</td></tr><tr><td><strong>Working</strong></td><td>Being generated (a progress bar is shown)</td></tr><tr><td><strong>ready</strong></td><td>Successfully generated — use the download button</td></tr><tr><td><strong>failed</strong></td><td>An error occurred during generation</td></tr></tbody></table><p>When a report fails, you receive a message in the app if <strong>Errors on report generation</strong> is on in your notification settings. Whether that message is also emailed depends on your email settings.</p><h3 id="document-status" tabindex="-1">Document status <a class="header-anchor" href="#document-status" aria-label="Permalink to &quot;Document status&quot;">​</a></h3><p>The <strong>Document status</strong> column is separate from the generation status. It says what the document is for: <em>For information</em>, <em>For ordering</em> or <em>Temporary</em>. The check icon in the row actions sets a report as <em>Final</em>.</p><h2 id="versioning" tabindex="-1">Versioning <a class="header-anchor" href="#versioning" aria-label="Permalink to &quot;Versioning&quot;">​</a></h2><p>Each time you regenerate a report, a new version is created: with the reload icon in the row, or by editing it and pressing <strong>Submit</strong>. All previous versions are kept. Expand the row to see the version history, where each version (rev 0, rev 1, …) can be downloaded or deleted. The download button in the row always gives the latest version.</p><div class="info custom-block"><p class="custom-block-title">Design Updates</p><p>If a design&#39;s IFC file is updated after a report was generated, a red warning icon appears next to the report&#39;s status. Hover it to see which designs have a newer IFC. The same icon marks those panels in the report form. Regenerate the report to include the latest design changes; the warning then goes away.</p></div><h2 id="content-selection" tabindex="-1">Content Selection <a class="header-anchor" href="#content-selection" aria-label="Permalink to &quot;Content Selection&quot;">​</a></h2><p>Most reports require you to select which content to include:</p><ul><li><strong>Assemblies / Modules</strong> — Select items from the project tree (phase → batch → panel). Panels that are already ready are greyed out and marked <em>ready</em>. <strong>Sort by priority</strong> orders the tree by production order. QR Stickers can include modules; the other reports work on assemblies.</li><li><strong>Part Batches</strong> — Some reports (Plates BoM, Wood BoM, Accessories BoM, the Wood and Plates CSVs and several machine files) have a <strong>Select by Part Batches</strong> switch to select part batches instead, which groups parts across assemblies.</li><li><strong>Rack loads</strong> — Rack Load Stickers are made for rack loads, picked from a list.</li></ul><h2 id="project-reports-vs-company-reports" tabindex="-1">Project Reports vs. Company Reports <a class="header-anchor" href="#project-reports-vs-company-reports" aria-label="Permalink to &quot;Project Reports vs. Company Reports&quot;">​</a></h2><p><strong>Project reports</strong> are generated from a specific project&#39;s data. Inside a project, every report type is available, including all Bills of Materials, stickers and machine files.</p><p><strong>Company reports</strong> are made in the company-wide Production files and Management files, when you need data across all projects. Only these types are offered there:</p><ul><li>Production Excel (Production files)</li><li>Worktime Excel (Management files)</li><li>Quality Control Report (Management files)</li><li>Issues Report (Management files)</li></ul><p>If your company plans production by date, the company-wide views offer the project types too. There you pick panels by <strong>production line</strong> and a <strong>From</strong> / <strong>To</strong> date range instead of a project tree.</p><h2 id="report-types" tabindex="-1">Report Types <a class="header-anchor" href="#report-types" aria-label="Permalink to &quot;Report Types&quot;">​</a></h2><h3 id="bills-of-materials" tabindex="-1">Bills of Materials <a class="header-anchor" href="#bills-of-materials" aria-label="Permalink to &quot;Bills of Materials&quot;">​</a></h3><p>PDF documents listing the parts needed for your constructibles:</p><ul><li><a href="/guide/reports/plates_bom/"><strong>Plates BoM</strong></a> — All plate parts with quantities and dimensions.</li><li><a href="/guide/reports/wood_bom/"><strong>Wood BoM</strong></a> — All wood/profile parts.</li><li><a href="/guide/reports/designs_bom/"><strong>Per-Design BoM</strong></a> — One BoM per unique design.</li><li><a href="/guide/reports/accesories_bom/"><strong>Accessories BoM</strong></a> — Accessories and hardware list.</li><li><a href="/guide/reports/custom_woodcsv/"><strong>Custom Woods CSV</strong></a> — Wood parts exported as CSV.</li><li><a href="/guide/reports/custom_platecsv/"><strong>Custom Plates CSV</strong></a> — Plate parts exported as CSV.</li><li><a href="/guide/reports/custom_accesorycsv/"><strong>Custom Accessories CSV</strong></a> — Accessories exported as CSV.</li></ul><h3 id="other-reports" tabindex="-1">Other Reports <a class="header-anchor" href="#other-reports" aria-label="Permalink to &quot;Other Reports&quot;">​</a></h3><ul><li><a href="/guide/reports/production_excel/"><strong>Production Excel</strong></a> — Spreadsheet with one row per panel and its dimensions and areas.</li><li><a href="/guide/reports/worktime_excel/"><strong>Worktime Excel</strong></a> — Production time per panel, or per panel and station.</li><li><a href="/guide/reports/quality_control/"><strong>Quality Control Report</strong></a> — PDF summarizing quality control records.</li><li><a href="/guide/reports/issues/"><strong>Issues Report</strong></a> — PDF listing all issues found during production.</li><li><a href="/guide/reports/qr_stickers/"><strong>QR Stickers</strong></a> — Printable QR code labels for panels and modules, and Rack Load Stickers for rack loads.</li></ul><h3 id="machine-files" tabindex="-1">Machine Files <a class="header-anchor" href="#machine-files" aria-label="Permalink to &quot;Machine Files&quot;">​</a></h3><p>Machine-specific file formats for CNC equipment. See the <a href="/guide/machine_files/formats/panel_mob1/">Machine Files</a> section for details.</p>',46),d=[l];function p(h,c,u,g,m,f){return t(),o("div",null,d)}const w=e(n,[["render",p]]);export{b as __pageData,w as default};
